window.ACTIVIDADES_RESPALDO = [{"id":"slime","cat":"crafts","minAge":5,"maxAge":10,"emoji":"🧪","time":"20 min","es":{"title":"Slime Casero Básico","cat":"✂️ Manualidades","materials":["1 taza de pegamento blanco","1 cucharada de bicarbonato","Colorante (el color que quieras)","1 cucharada de solución para lentes de contacto"],"steps":["Coloca el pegamento en un recipiente grande.","Agrega el bicarbonato y mezcla bien.","Añade el colorante de tu color favorito.","Agrega la solución para lentes de contacto lentamente.","Mezcla hasta que el slime se despegue del recipiente."],"benefits":["Motricidad fina","Estimulación sensorial","Creatividad"],"tip":"Si el slime queda muy pegajoso, agrega un poco más de solución para lentes."},"en":{"title":"Homemade Slime","cat":"✂️ Crafts","materials":["1 cup white glue","1 tbsp baking soda","Food coloring (your favorite color)","1 tbsp contact lens solution"],"steps":["Put the glue in a large bowl.","Add baking soda and mix well.","Add your favorite food coloring.","Slowly add the contact lens solution.","Mix until the slime no longer sticks to the bowl."],"benefits":["Fine motor skills","Sensory stimulation","Creativity"],"tip":"If the slime is too sticky, add a little more contact lens solution."}},{"id":"volcan","cat":"science","minAge":4,"maxAge":10,"emoji":"🌋","time":"15 min","es":{"title":"Volcán Casero","cat":"🔬 Experimentos","materials":["Vinagre blanco","Bicarbonato de sodio","Botella pequeña","Colorante rojo","Bandeja grande"],"steps":["Coloca la botella en el centro de la bandeja.","Vierte bicarbonato dentro de la botella.","Agrega el colorante rojo.","Vierte el vinagre lentamente.","¡Observa la erupción y repite las veces que quieras!"],"benefits":["Reacciones químicas","Observación científica","Diversión educativa"],"tip":"Coloca una toalla debajo de la bandeja para facilitar la limpieza."},"en":{"title":"Homemade Volcano","cat":"🔬 Science","materials":["White vinegar","Baking soda","Small bottle","Red food coloring","Large tray"],"steps":["Place the bottle in the center of the tray.","Pour baking soda inside the bottle.","Add red food coloring.","Slowly pour the vinegar.","Watch the eruption — repeat as many times as you like!"],"benefits":["Chemical reactions","Scientific observation","Educational fun"],"tip":"Place a towel under the tray for easy cleanup."}},{"id":"avion","cat":"crafts","minAge":5,"maxAge":12,"emoji":"✈️","time":"20 min","es":{"title":"Aviones de Papel","cat":"✂️ Manualidades","materials":["Hojas de papel (tamaño carta)","Marcadores de colores"],"steps":["Dobla el papel por la mitad a lo largo.","Dobla las esquinas superiores hacia el centro formando un triángulo.","Dobla las alas hacia abajo siguiendo la línea central.","Decora tu avión con los marcadores.","Organiza una competencia: ¿quién llega más lejos?"],"benefits":["Coordinación fina","Creatividad","Física básica (aerodinámica)"],"tip":"Dobla con cuidado — los bordes bien marcados hacen volar mejor al avión."},"en":{"title":"Paper Airplanes","cat":"✂️ Crafts","materials":["Letter-size paper sheets","Colored markers"],"steps":["Fold the paper in half lengthwise.","Fold the top corners inward to the center, forming a triangle.","Fold the wings down along the center line.","Decorate your airplane with markers.","Hold a contest: who flies farthest?"],"benefits":["Fine coordination","Creativity","Basic physics (aerodynamics)"],"tip":"Fold carefully — crisp edges make the airplane fly better."}},{"id":"huerto","cat":"science","minAge":4,"maxAge":10,"emoji":"🌱","time":"30 min + seguimiento / 30 min + tracking","es":{"title":"Mini Huerto Casero","cat":"🔬 Experimentos","materials":["Vasos de plástico o yogurt","Tierra para macetas","Semillas (frijol, lenteja o chía)","Agua"],"steps":["Llena los vasos con tierra hasta ¾.","Haz un hueco pequeño con el dedo y coloca la semilla.","Cubre con un poco de tierra.","Riega con una cucharada de agua.","Observa y riega cada día. Anota cuándo aparece el primer brote."],"benefits":["Responsabilidad diaria","Aprendizaje sobre naturaleza","Paciencia"],"tip":"Pon los vasos cerca de una ventana con luz solar. Las lentejas brotan en 3-4 días."},"en":{"title":"Mini Home Garden","cat":"🔬 Science","materials":["Plastic cups or yogurt containers","Potting soil","Seeds (bean, lentil or chia)","Water"],"steps":["Fill cups ¾ full with soil.","Make a small hole with your finger and place the seed.","Cover with a little soil.","Water with one tablespoon of water.","Observe and water daily. Note when the first sprout appears."],"benefits":["Daily responsibility","Learning about nature","Patience"],"tip":"Place cups near a sunny window. Lentils sprout in 3-4 days."}},{"id":"torre","cat":"science","minAge":5,"maxAge":12,"emoji":"🏗️","time":"20 min","es":{"title":"Torre de Malvaviscos","cat":"🔬 Experimentos","materials":["Malvaviscos (1 bolsa)","Palillos de dientes (1 caja)"],"steps":["Conecta los malvaviscos con palillos formando cuadrados.","Apila las estructuras para ir subiendo la torre.","Construye la torre más alta y estable posible.","Mide la altura con una regla.","¡Compara alturas con todos los participantes!"],"benefits":["Resolución de problemas","Ingeniería básica","Trabajo en equipo"],"tip":"Las bases más anchas hacen torres más estables. ¡Experimenta con las formas!"},"en":{"title":"Marshmallow Tower","cat":"🔬 Science","materials":["Marshmallows (1 bag)","Toothpicks (1 box)"],"steps":["Connect marshmallows with toothpicks to form squares.","Stack the structures to build your tower higher.","Build the tallest and most stable tower you can.","Measure the height with a ruler.","Compare heights with everyone who played!"],"benefits":["Problem solving","Basic engineering","Teamwork"],"tip":"Wider bases make more stable towers. Experiment with different shapes!"}},{"id":"pizza","cat":"cooking","minAge":5,"maxAge":12,"emoji":"🍕","time":"45 min","es":{"title":"Mini Pizzas en Casa","cat":"🍳 Cocina","materials":["Masa de pizza (comprada o casera)","Salsa de tomate","Queso mozzarella rallado","Toppings a elección: jamón, aceitunas, pimientos, etc."],"steps":["Precalienta el horno a 200°C.","Divide la masa en porciones pequeñas (una por niño).","Estira cada porción con las manos.","Cada niño decora su pizza como quiera.","Hornea 12-15 minutos hasta que el queso burbujee."],"benefits":["Creatividad culinaria","Nutrición","Trabajo en equipo"],"tip":"¡Deja que cada niño nombre su pizza. Hace que se la coman con más orgullo!"},"en":{"title":"Mini Pizzas at Home","cat":"🍳 Cooking","materials":["Pizza dough (store-bought or homemade)","Tomato sauce","Shredded mozzarella cheese","Toppings of choice: ham, olives, peppers, etc."],"steps":["Preheat the oven to 400°F (200°C).","Divide the dough into small portions (one per child).","Each child stretches their portion by hand.","Everyone decorates their pizza however they like.","Bake 12-15 minutes until the cheese bubbles."],"benefits":["Culinary creativity","Nutrition","Teamwork"],"tip":"Let each child name their pizza — they'll eat it with extra pride!"}},{"id":"burbujas","cat":"science","minAge":3,"maxAge":10,"emoji":"💦","time":"10 min","es":{"title":"Burbujas Gigantes","cat":"🔬 Experimentos","materials":["½ taza de agua","2 cucharadas de jabón lavavajillas","1 cucharada de glicerina o miel","Palitos o pajillas"],"steps":["Mezcla el agua, el jabón y la glicerina en un recipiente amplio.","Deja reposar la mezcla 5 minutos.","Sumerge los palitos o pajillas en la mezcla.","Sopla suavemente para crear burbujas.","¡Experimenta soplando más despacio o más rápido para hacer burbujas de distintos tamaños!"],"benefits":["Comprensión de tensión superficial","Coordinación respiratoria","Exploración sensorial"],"tip":"La glicerina hace las burbujas más resistentes. Si no tienes, usa miel o jarabe de maíz."},"en":{"title":"Giant Bubbles","cat":"🔬 Science","materials":["½ cup water","2 tbsp dish soap","1 tbsp glycerin or honey","Sticks or straws"],"steps":["Mix the water, soap and glycerin in a wide bowl.","Let the mixture rest 5 minutes.","Dip the sticks or straws into the mixture.","Blow gently to create bubbles.","Experiment blowing slower or faster to make different sizes!"],"benefits":["Understanding surface tension","Breath coordination","Sensory exploration"],"tip":"Glycerin makes bubbles stronger. No glycerin? Use honey or corn syrup instead."}},{"id":"playdough","cat":"crafts","minAge":3,"maxAge":8,"emoji":"🎨","time":"25 min","es":{"title":"Masa Moldeable de Colores","cat":"✂️ Manualidades","materials":["1 taza de harina","¼ taza de sal","½ taza de agua caliente","1 cucharada de aceite vegetal","Colorante alimentario"],"steps":["Mezcla la harina y la sal en un recipiente.","Agrega el aceite y el agua caliente poco a poco.","Amasa hasta obtener una textura suave y no pegajosa.","Divide en porciones y añade un color diferente a cada una.","¡Guarda en bolsas con cierre — dura hasta una semana!"],"benefits":["Motricidad fina","Creatividad libre","Relajación sensorial"],"tip":"Si queda muy pegajosa agrega más harina; si queda seca, unas gotas de agua."},"en":{"title":"Colorful Playdough","cat":"✂️ Crafts","materials":["1 cup flour","¼ cup salt","½ cup warm water","1 tbsp vegetable oil","Food coloring"],"steps":["Mix flour and salt in a bowl.","Add oil and warm water little by little.","Knead until smooth and non-sticky.","Divide into portions and add a different color to each.","Store in zip-lock bags — it lasts up to a week!"],"benefits":["Fine motor skills","Free creativity","Sensory relaxation"],"tip":"Too sticky? Add more flour. Too dry? Add a few drops of water."}},{"id":"galletas","cat":"cooking","minAge":4,"maxAge":12,"emoji":"🍪","time":"60 min","es":{"title":"Galletas Decoradas","cat":"🍳 Cocina","materials":["2 tazas de harina","½ taza de mantequilla blanda","½ taza de azúcar","1 huevo","1 cucharadita de vainilla","Azúcar glass y colorante para decorar"],"steps":["Bate la mantequilla con el azúcar hasta obtener una crema.","Agrega el huevo y la vainilla, mezcla bien.","Incorpora la harina poco a poco hasta formar una masa.","Refrigera 20 min, extiende con rodillo y corta figuras.","Hornea a 180 °C por 10–12 min. Decora cuando estén frías."],"benefits":["Matemáticas (medidas)","Coordinación manual","Creatividad artística"],"tip":"Usa cortadores con formas de estrellas, corazones y animales para más diversión."},"en":{"title":"Decorated Cookies","cat":"🍳 Cooking","materials":["2 cups flour","½ cup softened butter","½ cup sugar","1 egg","1 tsp vanilla extract","Powdered sugar and food coloring for decorating"],"steps":["Beat butter and sugar until creamy.","Add egg and vanilla, mix well.","Gradually add flour until a dough forms.","Refrigerate 20 min, roll out and cut shapes.","Bake at 350 °F for 10–12 min. Decorate when cool."],"benefits":["Math (measurements)","Hand coordination","Artistic creativity"],"tip":"Use star, heart and animal cookie cutters for extra fun."}},{"id":"titeres","cat":"crafts","minAge":4,"maxAge":10,"emoji":"🧦","time":"30 min","es":{"title":"Títeres de Calcetín","cat":"✂️ Manualidades","materials":["Calcetines viejos (uno por niño)","Ojos movibles o botones","Pegamento o hilo y aguja","Fieltro, lana o tela de colores","Marcadores permanentes"],"steps":["Pon el calcetín en tu mano y dobla los dedos para formar la boca.","Pega los ojos movibles encima del pliegue de la boca.","Corta cabello de fieltro o lana y pégalo.","Agrega detalles con marcadores: nariz, lengua, manchas.","¡Inventa un nombre y una voz especial para tu personaje!"],"benefits":["Expresión oral y dramática","Creatividad","Motricidad fina"],"tip":"Organiza una función de títeres al final. ¡Los niños adorarán actuar con sus personajes!"},"en":{"title":"Sock Puppets","cat":"✂️ Crafts","materials":["Old socks (one per child)","Googly eyes or buttons","Glue or needle and thread","Felt, yarn or colored fabric","Permanent markers"],"steps":["Put the sock on your hand and fold your fingers to make a mouth.","Glue googly eyes above the mouth fold.","Cut hair or bangs from felt or yarn and glue them on.","Add details with markers: nose, tongue, spots.","Invent a name and a special voice for your character!"],"benefits":["Oral and dramatic expression","Creativity","Fine motor skills"],"tip":"Put on a puppet show at the end — kids love performing with their characters!"}},{"id":"smoothie","cat":"cooking","minAge":4,"maxAge":10,"emoji":"🥤","time":"10 min","es":{"title":"Smoothie de Frutas","cat":"🍳 Cocina","materials":["1 banana madura","1 taza de fresas u otras frutas","½ taza de leche o yogur natural","Hielo (opcional)","Miel al gusto"],"steps":["Pela y corta las frutas en trozos pequeños.","Coloca todo en la licuadora: frutas, leche y miel.","Agrega hielo si lo quieres más frío.","Licúa a velocidad alta 30 segundos.","Sirve en vasos y decora el borde con una rodaja de fruta."],"benefits":["Hábitos alimenticios saludables","Medición y proporciones","Autonomía en cocina"],"tip":"¡Mezcla frutas de distintos colores y convierte el smoothie en un arcoíris!"},"en":{"title":"Fruit Smoothie","cat":"🍳 Cooking","materials":["1 ripe banana","1 cup strawberries or other fruit","½ cup milk or plain yogurt","Ice (optional)","Honey to taste"],"steps":["Peel and cut the fruit into small pieces.","Put everything in the blender: fruit, milk and honey.","Add ice for an extra-cold smoothie.","Blend on high for 30 seconds.","Serve in glasses and decorate the rim with a fruit slice."],"benefits":["Healthy eating habits","Measuring and proportions","Kitchen independence"],"tip":"Mix fruits of different colors to turn your smoothie into a rainbow!"}},{"id":"soplado","cat":"drawing","minAge":4,"maxAge":10,"emoji":"🌬️","time":"20 min","es":{"title":"Arte con Soplado","cat":"🎨 Arte","materials":["Pintura lavable de varios colores","Pajillas","Cartulina o papel grueso","Un poco de agua","Periódico para proteger la mesa"],"steps":["Cubre la mesa con periódico.","Diluye la pintura con un poco de agua para hacerla más fluida.","Coloca gotas de pintura sobre la cartulina.","Usa la pajilla para soplar la pintura en distintas direcciones.","Mezcla colores: observa cómo se crean nuevos tonos al combinarse."],"benefits":["Expresión artística libre","Coordinación respiratoria","Comprensión del color"],"tip":"Dobla el papel por la mitad mientras la pintura está húmeda para crear diseños simétricos."},"en":{"title":"Blow Art","cat":"🎨 Art","materials":["Washable paint in several colors","Straws","Cardstock or thick paper","A little water","Newspaper to protect the table"],"steps":["Cover the table with newspaper.","Dilute the paint with a little water to make it more fluid.","Drop spots of paint onto the cardstock.","Use the straw to blow the paint in different directions.","Mix colors — watch new shades form where they meet."],"benefits":["Free artistic expression","Breath coordination","Color theory"],"tip":"Fold the paper in half while the paint is still wet to create symmetrical designs."}},{"id":"puente","cat":"science","minAge":6,"maxAge":12,"emoji":"🌉","time":"25 min","es":{"title":"Reto del Puente","cat":"🔬 Experimentos","materials":["20 palitos de madera o de helado","Cinta adhesiva","Tijeras","Monedas para probar el peso","Dos pilas de libros (los apoyos del puente)"],"steps":["Coloca dos pilas de libros separadas unos 20 cm.","El reto: construir un puente que las cruce usando solo palitos y cinta.","Dibuja tu diseño en papel antes de construir.","Construye el puente en 15 minutos.","¡Prueba cuánto peso aguanta colocando monedas una a una!"],"benefits":["Pensamiento ingenieril","Resolución de problemas","Trabajo en equipo"],"tip":"Los triángulos son más resistentes que los cuadrados — ¡el secreto de los ingenieros!"},"en":{"title":"Bridge Challenge","cat":"🔬 Science","materials":["20 wooden craft sticks","Tape","Scissors","Coins to test weight","Two stacks of books (bridge supports)"],"steps":["Place two stacks of books about 20 cm apart.","Challenge: build a bridge spanning the gap using only sticks and tape.","Sketch your design on paper before building.","Build the bridge in 15 minutes.","Test how much weight it holds by adding coins one at a time!"],"benefits":["Engineering thinking","Problem solving","Teamwork"],"tip":"Triangles are stronger than squares — that's the engineer's secret!"}},{"id":"ensalada","cat":"cooking","minAge":3,"maxAge":10,"emoji":"🥗","time":"15 min","es":{"title":"Ensalada de Frutas Arcoíris","cat":"🍳 Cocina","materials":["Fresas o sandía (rojo)","Mandarina o naranja (naranja)","Piña o mango (amarillo)","Kiwi o uvas verdes (verde)","Arándanos o uvas moradas (morado)","Miel y jugo de limón al gusto"],"steps":["Lava todas las frutas cuidadosamente.","Corta en trozos del mismo tamaño (con ayuda de un adulto).","Coloca las frutas por colores formando un arcoíris en el plato.","Mezcla la miel con el jugo de limón y rocía por encima.","¡Cuenta los colores del arcoíris y nómbralos antes de comer!"],"benefits":["Alimentación saludable","Colores y aprendizaje","Autonomía en cocina"],"tip":"¡Convierte el plato en un juego: cada color del arcoíris da un superpoder diferente!"},"en":{"title":"Rainbow Fruit Salad","cat":"🍳 Cooking","materials":["Strawberries or watermelon (red)","Mandarin or orange (orange)","Pineapple or mango (yellow)","Kiwi or green grapes (green)","Blueberries or purple grapes (purple)","Honey and lime juice to taste"],"steps":["Wash all the fruit carefully.","Cut into equal-sized pieces (with adult help).","Arrange the fruit by color to form a rainbow on the plate.","Mix honey with lime juice and drizzle over the top.","Count the rainbow colors and name them before eating!"],"benefits":["Healthy eating","Colors and learning","Kitchen independence"],"tip":"Make it a game: each rainbow color gives a different superpower!"}},{"id":"densidades","cat":"science","minAge":5,"maxAge":12,"emoji":"🌈","time":"20 min","es":{"title":"Arcoíris de Densidades","cat":"🔬 Experimentos","materials":["Miel (100 ml)","Jabón lavavajillas (100 ml)","Agua con colorante azul (100 ml)","Aceite vegetal (100 ml)","Alcohol isopropílico con colorante rojo (100 ml)","Vaso alto y transparente","Jeringa o cuchara para verter despacio"],"steps":["Vierte la miel en el fondo del vaso muy despacio.","Agrega el jabón lavavajillas inclinando el vaso.","Vierte el agua coloreada con una cuchara para no mezclarla.","Añade el aceite vegetal con cuidado.","Termina con el alcohol de color rojo muy despacio. ¡Observa el arcoíris!"],"benefits":["Concepto de densidad","Método científico","Observación y registro"],"tip":"Vierte cada líquido muy despacio por el borde del vaso. La paciencia es clave."},"en":{"title":"Density Rainbow","cat":"🔬 Science","materials":["Honey (100 ml)","Dish soap (100 ml)","Water with blue food coloring (100 ml)","Vegetable oil (100 ml)","Rubbing alcohol with red food coloring (100 ml)","Tall clear glass","Syringe or spoon for slow pouring"],"steps":["Pour honey into the bottom of the glass very slowly.","Add dish soap by tilting the glass.","Pour the colored water over a spoon so it doesn't mix.","Carefully add the vegetable oil.","Finish with the red alcohol very slowly. Look at the rainbow!"],"benefits":["Density concept","Scientific method","Observation and recording"],"tip":"Pour each liquid very slowly down the side of the glass. Patience is key!"}},{"id":"estatica","cat":"science","minAge":4,"maxAge":10,"emoji":"⚡","time":"15 min","es":{"title":"Electricidad Estática","cat":"🔬 Experimentos","materials":["1 globo inflado","Cabello limpio y seco (o suéter de lana)","Pimienta molida","Un vaso de agua","Papelitos pequeños recortados"],"steps":["Frota el globo contra tu cabello por 10 segundos.","Acerca el globo a los papelitos — ¡saltarán hacia él!","Frota el globo de nuevo y acércalo al chorrito de agua del grifo.","¡Observa cómo el chorro se dobla hacia el globo!","Esparce pimienta en un plato y acerca el globo cargado."],"benefits":["Introducción a la electricidad","Observación científica","Pensamiento causal"],"tip":"Funciona mejor en días secos. La humedad reduce la carga estática del globo."},"en":{"title":"Static Electricity","cat":"🔬 Science","materials":["1 inflated balloon","Clean dry hair (or wool sweater)","Ground pepper","A glass of water","Small cut paper pieces"],"steps":["Rub the balloon against your hair for 10 seconds.","Hold the balloon near the paper pieces — they'll jump toward it!","Rub the balloon again and hold it near a thin stream of water from the tap.","Watch the stream bend toward the balloon!","Sprinkle pepper on a plate and hold the charged balloon above it."],"benefits":["Introduction to electricity","Scientific observation","Cause-and-effect thinking"],"tip":"Works best on dry days. Humidity reduces the static charge on the balloon."}},{"id":"cristales","cat":"science","minAge":6,"maxAge":12,"emoji":"💎","time":"30 min + 3 días","es":{"title":"Cristales de Sal","cat":"🔬 Experimentos","materials":["1 taza de agua caliente","½ taza de sal de cocina o bórax","Hilo de lana o cuerda","Palito de madera o lápiz","Colorante alimentario (opcional)","Vaso o frasco"],"steps":["Disuelve la sal en el agua caliente revolviendo hasta que no se disuelva más.","Agrega colorante si deseas cristales de colores.","Ata el hilo al palito y coloca el palito sobre el vaso para que cuelgue.","Vierte la solución en el vaso y cubre con papel.","Observa cada día — ¡en 3-5 días tendrás cristales brillantes!"],"benefits":["Concepto de saturación","Paciencia y observación diaria","Método científico"],"tip":"Cuanto más saturada esté la solución, más rápido y grandes crecerán los cristales."},"en":{"title":"Salt Crystals","cat":"🔬 Science","materials":["1 cup hot water","½ cup table salt or borax","Wool thread or string","Wooden stick or pencil","Food coloring (optional)","Glass or jar"],"steps":["Dissolve salt in hot water, stirring until no more dissolves.","Add food coloring if you want colored crystals.","Tie the thread to the stick and lay the stick across the glass so the thread hangs in.","Pour the solution into the glass and cover with paper.","Observe daily — in 3-5 days you'll have sparkling crystals!"],"benefits":["Saturation concept","Patience and daily observation","Scientific method"],"tip":"The more saturated the solution, the faster and bigger the crystals will grow."}},{"id":"barco_jabon","cat":"science","minAge":4,"maxAge":10,"emoji":"🚢","time":"15 min","es":{"title":"Barco de Jabón","cat":"🔬 Experimentos","materials":["Cartón o cartulina","Tijeras","Jabón lavavajillas","Bandeja o fuente con agua","Marcadores para decorar"],"steps":["Recorta un triángulo pequeño de cartón (tu barco).","Haz una pequeña muesca en V en la parte trasera del triángulo.","Decora el barco con marcadores.","Coloca el barco en la superficie del agua.","Pon una gota de jabón en la muesca — ¡el barco saldrá disparado!"],"benefits":["Tensión superficial","Acción y reacción","Pensamiento científico"],"tip":"El experimento solo funciona una vez por fuente de agua — el jabón rompe la tensión de toda la superficie."},"en":{"title":"Soap-Powered Boat","cat":"🔬 Science","materials":["Cardboard or cardstock","Scissors","Dish soap","Tray or basin with water","Markers for decorating"],"steps":["Cut a small triangle from cardboard (your boat).","Make a small V-notch at the back of the triangle.","Decorate the boat with markers.","Place the boat on the water surface.","Put one drop of soap in the notch — the boat will shoot forward!"],"benefits":["Surface tension","Action and reaction","Scientific thinking"],"tip":"The experiment only works once per tray — the soap breaks the surface tension of all the water."}},{"id":"germinacion","cat":"science","minAge":3,"maxAge":10,"emoji":"🌱","time":"15 min + seguimiento","es":{"title":"Germinación en Bolsa","cat":"🔬 Experimentos","materials":["Bolsa con cierre zip","Papel de cocina húmedo","Semillas (frijol, lenteja o chía)","Cinta adhesiva","Marcador para etiquetar","Ventana soleada"],"steps":["Humedece el papel de cocina y dóblalo dentro de la bolsa.","Coloca 2-3 semillas entre el papel y la pared transparente de la bolsa.","Cierra la bolsa y pégala en la ventana con cinta.","Etiqueta con la fecha y el tipo de semilla.","Registra cada día: ¿cuándo aparece la raíz? ¿cuándo el tallo?"],"benefits":["Ciclo de vida de las plantas","Registro científico diario","Responsabilidad y paciencia"],"tip":"Las lentejas germinan en 2-3 días, los frijoles en 4-5. ¡Prueba las dos y compara!"},"en":{"title":"Bag Germination","cat":"🔬 Science","materials":["Zip-lock bag","Wet paper towel","Seeds (bean, lentil or chia)","Tape","Marker for labeling","Sunny window"],"steps":["Wet the paper towel and fold it inside the bag.","Place 2-3 seeds between the paper and the transparent wall of the bag.","Seal the bag and tape it to the window.","Label with the date and seed type.","Record daily: when does the root appear? When does the stem?"],"benefits":["Plant life cycle","Daily scientific recording","Responsibility and patience"],"tip":"Lentils sprout in 2-3 days, beans in 4-5. Try both and compare!"}},{"id":"colores_agua","cat":"science","minAge":3,"maxAge":8,"emoji":"🌀","time":"10 min","es":{"title":"Colores que Bailan","cat":"🔬 Experimentos","materials":["Frasco o vaso transparente","Agua","Aceite vegetal (¼ taza)","Colorante alimentario de varios colores","Cuchara o palito para agitar"],"steps":["Llena el frasco con agua hasta la mitad.","Vierte el aceite por encima — verás que se separa.","Agrega gotas de distintos colorantes sobre el aceite.","Observa cómo las gotas caen a través del aceite y se disuelven en el agua.","Agita suavemente y observa los remolinos de color bailar."],"benefits":["Inmiscibilidad de líquidos","Densidad","Asombro científico"],"tip":"Para un efecto dramático, usa al menos 3 colores distintos y agrega las gotas desde altura."},"en":{"title":"Dancing Colors","cat":"🔬 Science","materials":["Clear jar or glass","Water","Vegetable oil (¼ cup)","Food coloring in several colors","Spoon or stick for stirring"],"steps":["Fill the jar halfway with water.","Pour oil on top — it will separate immediately.","Drop different food colorings onto the oil.","Watch the drops fall through the oil and dissolve in the water.","Swirl gently and watch the color tornadoes dance."],"benefits":["Liquid immiscibility","Density","Scientific wonder"],"tip":"For a dramatic effect, use at least 3 different colors and drop them from a height."}},{"id":"origami","cat":"crafts","minAge":6,"maxAge":12,"emoji":"🦢","time":"30 min","es":{"title":"Origami Fácil","cat":"✂️ Manualidades","materials":["Hojas de papel cuadradas de colores (15×15 cm)","Mesa limpia y plana","Regla (opcional)"],"steps":["BARCO: Dobla el cuadrado por la mitad, vuelve a doblar las esquinas hacia el centro, dobla el borde inferior hacia arriba por ambos lados y abre el barco desde el interior.","RANA SALTARINA: Dobla en triángulo dos veces, lleva las esquinas laterales al pico y dobla las patas hacia atrás. Presiona para que salte.","GRULLA: Dobla en forma de cometa, gira, repite, abre y aplana ambos lados, dobla las alas hacia afuera.","Practica cada figura al menos 2 veces.","¡Decora con marcadores y crea una escena con todas las figuras!"],"benefits":["Geometría y espacialidad","Concentración","Motricidad fina avanzada"],"tip":"El secreto del origami es marcar bien cada pliegue con la uña antes de continuar."},"en":{"title":"Easy Origami","cat":"✂️ Crafts","materials":["Colored square paper sheets (6×6 in)","Clean flat table","Ruler (optional)"],"steps":["BOAT: Fold square in half, fold again, bring corners to the center, fold bottom edge up on both sides, and open the boat from inside.","JUMPING FROG: Fold into triangle twice, bring side corners to the tip and fold legs back. Press to make it jump.","CRANE: Fold into kite shape, flip, repeat, open and flatten both sides, fold wings outward.","Practice each figure at least twice.","Decorate with markers and create a scene with all your figures!"],"benefits":["Geometry and spatial thinking","Concentration","Advanced fine motor skills"],"tip":"The secret of origami is to crease each fold firmly with your nail before moving on."}},{"id":"piedras","cat":"drawing","minAge":4,"maxAge":10,"emoji":"🌿","time":"45 min","es":{"title":"Jardín de Piedras Pintadas","cat":"🎨 Arte","materials":["Piedras lisas y limpias","Pintura acrílica o de dedos","Pinceles finos y gruesos","Barniz transparente (opcional)","Periódico para la mesa"],"steps":["Lava y seca bien las piedras.","Da una capa base de pintura blanca y deja secar 10 minutos.","Pinta tu diseño: animales, caras, mandalas o patrones.","Agrega detalles finos con un pincel delgado.","Cuando esté seco, aplica barniz para proteger y dar brillo."],"benefits":["Expresión artística","Paciencia y detalle","Conexión con la naturaleza"],"tip":"¡Esconde piedras pintadas en parques o plazas para que otros niños las encuentren!"},"en":{"title":"Painted Rock Garden","cat":"🎨 Art","materials":["Smooth clean rocks","Acrylic or finger paint","Fine and thick brushes","Clear varnish (optional)","Newspaper for the table"],"steps":["Wash and dry the rocks well.","Apply a white base coat and let dry 10 minutes.","Paint your design: animals, faces, mandalas or patterns.","Add fine details with a thin brush.","When dry, apply varnish to protect and add shine."],"benefits":["Artistic expression","Patience and attention to detail","Connection with nature"],"tip":"Hide your painted rocks in parks or plazas for other kids to find!"}},{"id":"cuento","cat":"drawing","minAge":5,"maxAge":12,"emoji":"📖","time":"30 min","es":{"title":"Inventa tu Cuento","cat":"✏️ Escritura","materials":["Esta ficha impresa","Lápiz o bolígrafo","Colores para ilustrar (opcional)"],"steps":["MI PERSONAJE: ¿Cómo se llama? ¿Qué poderes o talentos tiene? Dibújalo.","EL PROBLEMA: ¿Qué desafío enfrenta? ¿Por qué es difícil?","LA AVENTURA: Describe 3 cosas que hace para resolver el problema.","LA AYUDA: ¿Quién o qué lo ayuda en el camino?","EL FINAL: ¿Cómo termina la historia? ¿Qué aprende el personaje?"],"benefits":["Escritura creativa","Estructura narrativa","Vocabulario y expresión"],"tip":"Los mejores cuentos tienen un personaje con un defecto que supera al final. ¿Cuál es el de tu personaje?"},"en":{"title":"Invent Your Story","cat":"✏️ Writing","materials":["This printed sheet","Pencil or pen","Colors for illustrating (optional)"],"steps":["MY CHARACTER: What's their name? What powers or talents do they have? Draw them.","THE PROBLEM: What challenge do they face? Why is it hard?","THE ADVENTURE: Describe 3 things they do to solve the problem.","THE HELP: Who or what helps them along the way?","THE ENDING: How does the story end? What does the character learn?"],"benefits":["Creative writing","Narrative structure","Vocabulary and expression"],"tip":"The best stories have a character with a flaw they overcome. What's your character's flaw?"}},{"id":"yoga","cat":"other","minAge":3,"maxAge":10,"emoji":"🧘","time":"20 min","es":{"title":"Yoga Infantil","cat":"🌟 Bienestar","materials":["Una esterilla o toalla en el suelo","Ropa cómoda","Espacio despejado","Música suave (opcional)"],"steps":["MONTAÑA: De pie, pies juntos, brazos al lado. Respira profundo 3 veces.","ÁRBOL: Un pie en el tobillo contrario, manos juntas arriba. Equilibrio 10 seg.","PERRO BOCA ABAJO: Manos y pies en el suelo, cadera arriba, forma una V.","COBRA: Boca abajo, manos bajo los hombros, eleva el pecho.","NIÑO: Rodillas en el suelo, siéntate en los talones y estira los brazos al frente.","GUERRERO: Un pie adelante, rodilla doblada, brazos extendidos.","MARIPOSA: Sentado, plantas de los pies juntas, aletea las rodillas.","ESTRELLA DE MAR: Acostado boca arriba, brazos y piernas extendidos. Respira."],"benefits":["Equilibrio y coordinación","Regulación emocional","Conciencia corporal"],"tip":"Haz cada postura al ritmo de 5 respiraciones lentas. La calma llega sola."},"en":{"title":"Kids Yoga","cat":"🌟 Wellness","materials":["A mat or towel on the floor","Comfortable clothes","Clear space","Soft music (optional)"],"steps":["MOUNTAIN: Stand tall, feet together, arms at sides. Breathe deeply 3 times.","TREE: One foot on the opposite ankle, hands together above. Balance 10 sec.","DOWNWARD DOG: Hands and feet on floor, hips up, form an upside-down V.","COBRA: Face down, hands under shoulders, lift your chest.","CHILD'S POSE: Knees on floor, sit back on heels, stretch arms forward.","WARRIOR: One foot forward, knee bent, arms extended.","BUTTERFLY: Seated, soles of feet together, flap your knees like wings.","STARFISH: Lie on back, arms and legs wide. Breathe slowly."],"benefits":["Balance and coordination","Emotional regulation","Body awareness"],"tip":"Hold each pose for 5 slow breaths. Calmness comes naturally."}},{"id":"pulseras","cat":"crafts","minAge":6,"maxAge":12,"emoji":"🧵","time":"30 min","es":{"title":"Pulseras de Hilo","cat":"✂️ Manualidades","materials":["Hilo de bordar o lana de colores (3-4 colores)","Tijeras","Cinta adhesiva o pinza para sujetar","Tabla o libro para trabajar"],"steps":["Corta 4 hilos de unos 60 cm cada uno, uno de cada color.","Junta los extremos y haz un nudo dejando 5 cm de cola.","PATRÓN BÁSICO: Toma el primer hilo y haz nudos en forma de 4 sobre cada uno de los demás hilos de izquierda a derecha.","Repite con el siguiente hilo hasta llegar al ancho deseado.","Mide la pulsera en la muñeca y remata con un nudo firme."],"benefits":["Motricidad fina avanzada","Paciencia y concentración","Sentido del regalo y amistad"],"tip":"Asegura el nudo inicial con cinta a una mesa o libro para que no se mueva mientras trabajas."},"en":{"title":"Friendship Bracelets","cat":"✂️ Crafts","materials":["Embroidery floss or yarn in 3-4 colors","Scissors","Tape or clip to anchor","Board or book to work on"],"steps":["Cut 4 threads about 60 cm each, one of each color.","Knot the ends together leaving 5 cm tail.","BASIC PATTERN: Take the first thread and make figure-4 knots over each of the other threads from left to right.","Repeat with the next thread until you reach the desired length.","Measure the bracelet on the wrist and finish with a firm knot."],"benefits":["Advanced fine motor skills","Patience and concentration","Sense of gifting and friendship"],"tip":"Tape the starting knot to a table or book so it doesn't move while you work."}},{"id":"marcapaginas","cat":"crafts","minAge":5,"maxAge":12,"emoji":"🔖","time":"20 min","es":{"title":"Marcapáginas Decorados","cat":"✂️ Manualidades","materials":["Cartulina o cartón fino","Tijeras o cúter (con ayuda de adulto)","Marcadores, colores o acuarelas","Pegamento y recortes de revista o papel de regalo","Plastificadora o cinta adhesiva transparente para proteger"],"steps":["Recorta tiras de cartulina de 5×15 cm (una por marcapáginas).","TÉCNICA 1 — Dibujo libre: dibuja un personaje o paisaje con marcadores.","TÉCNICA 2 — Collage: pega recortes de revista y crea una composición colorida.","TÉCNICA 3 — Acuarela + contorno: pinta fondos y agrega tinta negra encima.","Cubre con cinta transparente o plastifica para que dure mucho más."],"benefits":["Lectura y amor por los libros","Creatividad artística","Motricidad fina"],"tip":"¡Regala los marcapáginas a amigos o familiares — son el regalo perfecto hecho a mano!"},"en":{"title":"Decorated Bookmarks","cat":"✂️ Crafts","materials":["Cardstock or thin cardboard","Scissors or craft knife (with adult help)","Markers, colored pencils or watercolors","Glue and magazine or gift-wrap scraps","Laminator or clear tape to protect"],"steps":["Cut strips of cardstock 5×15 cm (one per bookmark).","TECHNIQUE 1 — Free drawing: draw a character or landscape with markers.","TECHNIQUE 2 — Collage: glue magazine scraps into a colorful composition.","TECHNIQUE 3 — Watercolor + outline: paint backgrounds and add black ink on top.","Cover with clear tape or laminate so it lasts much longer."],"benefits":["Reading and love of books","Artistic creativity","Fine motor skills"],"tip":"Gift the bookmarks to friends or family — they're the perfect handmade present!"}},{"id":"corona","cat":"crafts","minAge":5,"maxAge":10,"emoji":"🌸","time":"30 min","es":{"title":"Corona de Flores de Papel","cat":"✂️ Manualidades","materials":["Papel de seda o papel crepé de colores","Tijeras","Alambre delgado floral o tiras de cartulina","Cinta adhesiva verde","Pegamento en barra"],"steps":["Corta cuadrados de papel de seda de 10×10 cm (6 por flor).","Apila 6 cuadrados, dóblalos en acordeón y ata el centro con alambre.","Separa las capas con cuidado hacia arriba para formar la flor.","Envuelve el alambre con cinta verde para hacer el tallo.","Mide una tira de cartulina para la cabeza y pega las flores hasta cubrir la corona."],"benefits":["Creatividad y diseño","Motricidad fina","Expresión personal"],"tip":"Mezcla flores de 2-3 colores diferentes para una corona más vistosa. ¡Úsala en fotos!"},"en":{"title":"Paper Flower Crown","cat":"✂️ Crafts","materials":["Tissue paper or crepe paper in colors","Scissors","Thin floral wire or cardstock strips","Green tape","Glue stick"],"steps":["Cut 10×10 cm squares of tissue paper (6 per flower).","Stack 6 squares, accordion-fold them and tie the center with wire.","Carefully separate the layers upward to shape the flower.","Wrap the wire with green tape to make the stem.","Measure a cardstock strip to fit the head and glue flowers all around."],"benefits":["Creativity and design","Fine motor skills","Personal expression"],"tip":"Mix flowers in 2-3 different colors for a more striking crown. Wear it for photos!"}},{"id":"movil","cat":"crafts","minAge":5,"maxAge":10,"emoji":"🎐","time":"35 min","es":{"title":"Móvil de Figuras","cat":"✂️ Manualidades","materials":["Cartulina de colores","Tijeras","Hilo o lana","Palito de madera o rama delgada (30 cm)","Marcadores y colores para decorar","Perforadora o aguja para los agujeros"],"steps":["Dibuja y recorta 5-7 figuras en cartulina (animales, estrellas, nubes, planetas).","Decora ambas caras de cada figura con colores.","Haz un agujero pequeño en la parte superior de cada figura.","Ata hilos de distintas longitudes a las figuras.","Cuelga todas las figuras de la rama y ajusta el equilibrio desplazando los hilos."],"benefits":["Equilibrio y física básica","Creatividad espacial","Decoración del entorno"],"tip":"Cuélgalo cerca de una ventana — la brisa lo hará girar lentamente como un móvil real."},"en":{"title":"Hanging Mobile","cat":"✂️ Crafts","materials":["Colored cardstock","Scissors","Thread or yarn","Wooden stick or thin branch (30 cm)","Markers and pencils to decorate","Hole punch or needle for holes"],"steps":["Draw and cut out 5-7 shapes in cardstock (animals, stars, clouds, planets).","Decorate both sides of each shape with colors.","Make a small hole at the top of each shape.","Tie threads of different lengths to the shapes.","Hang all shapes from the branch and balance by sliding the threads."],"benefits":["Balance and basic physics","Spatial creativity","Room decoration"],"tip":"Hang it near a window — the breeze will make it spin slowly like a real mobile."}},{"id":"caja","cat":"crafts","minAge":6,"maxAge":12,"emoji":"🎁","time":"30 min","es":{"title":"Caja de Regalo Decorada","cat":"✂️ Manualidades","materials":["Cartulina gruesa o cartón fino","Regla y lápiz","Tijeras y pegamento","Marcadores, colores o papel de regalo","Cinta o lazo para decorar"],"steps":["Dibuja una cruz con 4 cuadrados iguales de 8×8 cm y un rectángulo de 8×2 cm a cada lado.","Recorta la figura completa.","Dobla todos los bordes hacia adentro marcando las líneas con la regla.","Pega las pestañas para formar la caja.","Decora con marcadores, papel de regalo o cinta. ¡Lista para regalar!"],"benefits":["Geometría y medida","Planificación espacial","Generosidad"],"tip":"Haz la tapa 1 cm más grande que la caja base para que encaje perfectamente."},"en":{"title":"Decorated Gift Box","cat":"✂️ Crafts","materials":["Thick cardstock or thin cardboard","Ruler and pencil","Scissors and glue","Markers, colored pencils or gift wrap","Ribbon or bow for decoration"],"steps":["Draw a cross with 4 equal 8×8 cm squares and an 8×2 cm rectangle on each side.","Cut out the whole shape.","Fold all edges inward, creasing with the ruler.","Glue the tabs to form the box.","Decorate with markers, gift wrap or ribbon. Ready to give!"],"benefits":["Geometry and measurement","Spatial planning","Generosity"],"tip":"Make the lid 1 cm larger than the base so it fits perfectly."}},{"id":"acuarela","cat":"drawing","minAge":4,"maxAge":10,"emoji":"🎨","time":"25 min","es":{"title":"Pintura con Acuarelas","cat":"🎨 Arte","materials":["Acuarelas (en pastilla o líquidas)","Pinceles grueso, mediano y fino","Papel acuarela o papel grueso","Vaso con agua limpia","Papel de cocina para limpiar el pincel"],"steps":["LAVADO PLANO: moja bien el papel, aplica un color y deja que se extienda solo.","HÚMEDO SOBRE HÚMEDO: añade otro color mientras el primero aún está mojado — ¡se mezclan solos!","DEGRADADO: carga el pincel con un color oscuro y ve añadiendo agua para aclararlo progresivamente.","SALPICADO: carga el pincel, golpéalo con otro dedo para salpicar gotitas de color.","¡Combina las 4 técnicas en un solo cuadro!"],"benefits":["Técnica artística","Control del color y el agua","Paciencia y observación"],"tip":"Limpia el pincel entre colores para no ensuciar la paleta. El agua turbia da colores opacos."},"en":{"title":"Watercolor Painting","cat":"🎨 Art","materials":["Watercolors (pan or liquid)","Thick, medium and fine brushes","Watercolor or thick paper","Glass of clean water","Paper towel to clean brush"],"steps":["FLAT WASH: wet the paper well, apply a color and let it spread on its own.","WET ON WET: add another color while the first is still wet — they blend themselves!","GRADIENT: load the brush with a dark color and add water progressively to lighten.","SPLATTER: load the brush, tap it with another finger to splatter color drops.","Combine all 4 techniques in a single painting!"],"benefits":["Art technique","Color and water control","Patience and observation"],"tip":"Clean the brush between colors to keep the palette clean. Murky water makes muddy colors."}},{"id":"mosaico","cat":"drawing","minAge":5,"maxAge":12,"emoji":"🟦","time":"30 min","es":{"title":"Mosaico de Papel","cat":"🎨 Arte","materials":["Revistas viejas o papel de colores","Tijeras","Pegamento en barra","Cartulina negra o blanca","Lápiz para dibujar el contorno"],"steps":["Dibuja con lápiz el contorno de una figura simple en la cartulina (pez, sol, mariposa).","Recorta pequeños cuadrados o rectángulos de papel de colores (1×1 cm aprox).","Ordena los cuadraditos por colores antes de pegar.","Pega las piezas dentro del contorno dejando un pequeño espacio entre ellas.","Rellena también el fondo con cuadraditos de un color distinto."],"benefits":["Paciencia y precisión","Composición artística","Reconocimiento del color"],"tip":"Cuanto más pequeñas sean las piezas, más detallado y bonito quedará el mosaico."},"en":{"title":"Paper Mosaic","cat":"🎨 Art","materials":["Old magazines or colored paper","Scissors","Glue stick","Black or white cardstock","Pencil to draw the outline"],"steps":["Draw a simple shape outline in pencil on the cardstock (fish, sun, butterfly).","Cut small squares or rectangles from colored paper (about 1×1 cm).","Sort the pieces by color before gluing.","Glue the pieces inside the outline leaving a small gap between them.","Fill the background with pieces in a different color."],"benefits":["Patience and precision","Artistic composition","Color recognition"],"tip":"The smaller the pieces, the more detailed and beautiful the mosaic will look."}},{"id":"estampado","cat":"drawing","minAge":4,"maxAge":10,"emoji":"🥔","time":"25 min","es":{"title":"Estampado con Verduras","cat":"🎨 Arte","materials":["Papa, apio, pimiento o zanahoria","Cuchillo (uso de adulto)","Pintura acrílica o tempera lavable","Platos pequeños o paleta","Papel o tela para estampar","Periódico para la mesa"],"steps":["Un adulto corta las verduras por la mitad o en formas simples.","Vierte pintura en platos planos, una por color.","Presiona la verdura sobre la pintura y luego sobre el papel.","Experimenta con diferentes presiones: suave = luz, fuerte = relleno completo.","Combina varios vegetales para crear un cuadro lleno de texturas únicas."],"benefits":["Exploración de texturas","Composición visual","Conexión con los alimentos"],"tip":"El apio cortado transversalmente hace círculos perfectos. ¡La papa permite tallar cualquier forma!"},"en":{"title":"Vegetable Printing","cat":"🎨 Art","materials":["Potato, celery, bell pepper or carrot","Knife (adult use)","Acrylic or washable tempera paint","Small plates or palette","Paper or fabric for printing","Newspaper for the table"],"steps":["An adult cuts the vegetables in half or into simple shapes.","Pour paint into flat plates, one color per plate.","Press the vegetable onto the paint and then onto the paper.","Experiment with pressure: light = faint print, firm = full coverage.","Combine several vegetables to create artwork with unique textures."],"benefits":["Texture exploration","Visual composition","Connection with food"],"tip":"Celery cut crosswise makes perfect circles. Potatoes can be carved into any shape!"}},{"id":"atardecer","cat":"drawing","minAge":6,"maxAge":12,"emoji":"🌅","time":"25 min","es":{"title":"Siluetas de Atardecer","cat":"🎨 Arte","materials":["Papel blanco grueso o acuarela","Acuarelas o temperas (amarillo, naranja, rojo, morado)","Papel negro para las siluetas","Tijeras","Pegamento"],"steps":["Pinta el cielo con franjas horizontales de amarillo, naranja, rojo y morado de abajo a arriba.","Mezcla los colores ligeramente mientras están húmedos para transiciones suaves.","Deja secar completamente el fondo (15-20 min).","En papel negro, recorta siluetas de árboles, animales, casas o personas.","Pega las siluetas negras en el borde inferior del atardecer."],"benefits":["Técnica de capas y color","Contraste visual","Composición artística"],"tip":"Recorta siluetas bien sencillas — el contraste negro/atardecer hace todo el trabajo visual."},"en":{"title":"Sunset Silhouettes","cat":"🎨 Art","materials":["Thick white or watercolor paper","Watercolors or tempera (yellow, orange, red, purple)","Black paper for silhouettes","Scissors","Glue"],"steps":["Paint the sky with horizontal stripes of yellow, orange, red and purple from bottom to top.","Blend the colors slightly while wet for smooth transitions.","Let the background dry completely (15-20 min).","On black paper, cut out silhouettes of trees, animals, houses or people.","Glue the black silhouettes along the bottom edge of the sunset."],"benefits":["Layering and color technique","Visual contrast","Artistic composition"],"tip":"Cut very simple silhouettes — the black/sunset contrast does all the visual work."}},{"id":"tacos","cat":"cooking","minAge":4,"maxAge":12,"emoji":"🌮","time":"30 min","es":{"title":"Tacos Rápidos","cat":"🍳 Cocina","materials":["Tortillas de maíz o harina","Pollo cocido desmenuzado o frijoles","Lechuga y tomate picados","Queso rallado","Crema, salsa y limón","Sartén y espátula"],"steps":["Calienta la tortilla en la sartén 30 segundos por lado.","Coloca el pollo o frijoles en el centro de la tortilla.","Agrega lechuga, tomate y queso al gusto.","Añade crema y salsa.","Dobla y exprime limón por encima. ¡A disfrutar!"],"benefits":["Autonomía en cocina","Nutrición equilibrada","Diversidad cultural"],"tip":"Organiza todos los ingredientes en tazones pequeños — cada niño arma su taco a su gusto."},"en":{"title":"Quick Tacos","cat":"🍳 Cooking","materials":["Corn or flour tortillas","Cooked shredded chicken or beans","Chopped lettuce and tomato","Shredded cheese","Sour cream, salsa and lime","Skillet and spatula"],"steps":["Heat the tortilla in the skillet 30 seconds per side.","Place the chicken or beans in the center of the tortilla.","Add lettuce, tomato and cheese to taste.","Add sour cream and salsa.","Fold and squeeze lime over the top. Enjoy!"],"benefits":["Kitchen independence","Balanced nutrition","Cultural diversity"],"tip":"Set up all ingredients in small bowls — each child builds their own taco their way."}},{"id":"limonada","cat":"cooking","minAge":3,"maxAge":10,"emoji":"🍋","time":"10 min","es":{"title":"Limonada Casera","cat":"🍳 Cocina","materials":["4 limones","4 cucharadas de azúcar o miel","1 litro de agua fría","Hielo","Menta fresca (opcional)","Exprimidor y jarra"],"steps":["Exprime los 4 limones y vierte el jugo en la jarra.","Agrega el azúcar o miel y revuelve hasta disolver.","Vierte el agua fría y mezcla bien.","Agrega hielo y hojas de menta.","Prueba y ajusta: ¿necesita más limón, más dulce o más agua?"],"benefits":["Medición y proporciones","Equilibrio de sabores","Autonomía en cocina"],"tip":"VERSIÓN CON GAS: usa agua con gas en vez de agua normal — ¡queda deliciosa!"},"en":{"title":"Homemade Lemonade","cat":"🍳 Cooking","materials":["4 lemons","4 tbsp sugar or honey","1 liter cold water","Ice","Fresh mint (optional)","Juicer and pitcher"],"steps":["Squeeze the 4 lemons and pour the juice into the pitcher.","Add sugar or honey and stir until dissolved.","Pour in the cold water and mix well.","Add ice and mint leaves.","Taste and adjust: does it need more lemon, more sweet or more water?"],"benefits":["Measuring and proportions","Flavor balance","Kitchen independence"],"tip":"SPARKLING VERSION: use sparkling water instead of still water — absolutely delicious!"}},{"id":"muffins","cat":"cooking","minAge":4,"maxAge":12,"emoji":"🧁","time":"45 min","es":{"title":"Muffins de Banana","cat":"🍳 Cocina","materials":["3 bananas muy maduras","2 tazas de harina","½ taza de azúcar","1 huevo","⅓ taza de mantequilla derretida","1 cucharadita de polvo de hornear","Molde para muffins y capacillos"],"steps":["Aplasta las bananas con un tenedor hasta obtener un puré.","Mezcla el puré con el huevo, el azúcar y la mantequilla.","Agrega la harina y el polvo de hornear, mezcla sin batir demasiado.","Llena los capacillos hasta ¾ de su capacidad.","Hornea a 180 °C por 20-22 min hasta que un palillo salga limpio."],"benefits":["Química de hornear","Aprovechamiento de alimentos maduros","Satisfacción creativa"],"tip":"Cuanto más maduras y negras estén las bananas, más dulces y húmedos quedarán los muffins."},"en":{"title":"Banana Muffins","cat":"🍳 Cooking","materials":["3 very ripe bananas","2 cups flour","½ cup sugar","1 egg","⅓ cup melted butter","1 tsp baking powder","Muffin tin and liners"],"steps":["Mash the bananas with a fork until pureed.","Mix the puree with the egg, sugar and butter.","Add flour and baking powder — mix without over-beating.","Fill the liners ¾ full.","Bake at 350 °F for 20-22 min until a toothpick comes out clean."],"benefits":["Baking chemistry","Using overripe food","Creative satisfaction"],"tip":"The riper and blacker the bananas, the sweeter and more moist the muffins will be."}},{"id":"paletas","cat":"cooking","minAge":3,"maxAge":10,"emoji":"🍦","time":"15 min + congelado","es":{"title":"Paletas de Frutas","cat":"🍳 Cocina","materials":["Frutas variadas: fresas, mango, kiwi, piña","Jugo de naranja o leche de coco","Moldes para paletas o vasos pequeños","Palitos de madera o cucharas plásticas","Licuadora (opcional)"],"steps":["PALETA DE FRUTA ENTERA: corta frutas en trozos y colócalas en los moldes.","Rellena con jugo de naranja hasta cubrir las frutas.","PALETA DE PURÉ: licúa las frutas con un poco de jugo y vierte en los moldes.","Inserta el palito y congela al menos 4 horas o toda la noche.","Para desmoldar, pasa el molde bajo agua tibia 10 segundos."],"benefits":["Paciencia (esperar el resultado)","Alimentación saludable","Creatividad culinaria"],"tip":"Usa vasos de yogur y cucharas como moldes alternativos si no tienes moldes especiales."},"en":{"title":"Fruit Popsicles","cat":"🍳 Cooking","materials":["Assorted fruit: strawberries, mango, kiwi, pineapple","Orange juice or coconut milk","Popsicle molds or small cups","Wooden sticks or plastic spoons","Blender (optional)"],"steps":["WHOLE FRUIT POPSICLE: cut fruit into pieces and place them in the molds.","Fill with orange juice to cover the fruit.","PURÉE POPSICLE: blend fruit with a little juice and pour into molds.","Insert the stick and freeze at least 4 hours or overnight.","To unmold, run the mold under warm water for 10 seconds."],"benefits":["Patience (waiting for results)","Healthy eating","Culinary creativity"],"tip":"Use yogurt cups and spoons as alternative molds if you don't have popsicle molds."}},{"id":"pancakes","cat":"cooking","minAge":4,"maxAge":12,"emoji":"🥞","time":"20 min","es":{"title":"Pancakes con Formas","cat":"🍳 Cocina","materials":["1 taza de harina","1 taza de leche","1 huevo","2 cucharadas de mantequilla derretida","1 cucharadita de polvo de hornear","Sartén y espátula","Botella con pico (para formas)"],"steps":["Mezcla todos los ingredientes hasta obtener una mezcla homogénea.","Calienta la sartén a fuego medio y añade un poco de mantequilla.","FORMA BÁSICA: vierte la mezcla con cuchara para hacer círculos.","FORMAS ESPECIALES: usa una botella con pico para dibujar estrellas, corazones o letras.","Cuando aparezcan burbujas en la superficie, voltea con la espátula."],"benefits":["Coordinación y precisión","Química de hornear","Paciencia y observación"],"tip":"La botella con pico es el truco para hacer letras y formas perfectas. ¡Prueba escribir nombres!"},"en":{"title":"Shaped Pancakes","cat":"🍳 Cooking","materials":["1 cup flour","1 cup milk","1 egg","2 tbsp melted butter","1 tsp baking powder","Skillet and spatula","Squeeze bottle (for shapes)"],"steps":["Mix all ingredients until smooth.","Heat the skillet over medium heat and add a little butter.","BASIC SHAPE: pour batter with a spoon to make circles.","SPECIAL SHAPES: use a squeeze bottle to draw stars, hearts or letters.","When bubbles appear on the surface, flip with the spatula."],"benefits":["Coordination and precision","Baking chemistry","Patience and observation"],"tip":"The squeeze bottle is the trick for perfect letters and shapes. Try spelling names!"}},{"id":"tesoro","cat":"other","minAge":4,"maxAge":12,"emoji":"🗺️","time":"1 hora","es":{"title":"Búsqueda del Tesoro","cat":"🎮 Juegos","materials":["Esta ficha impresa (pistas y mapa)","Tijeras para recortar las tarjetas de pistas","Premio o \"tesoro\" escondido","Bolígrafo para personalizar las pistas","Cinta adhesiva para pegar pistas en lugares"],"steps":["Escoge 6 lugares en casa o el jardín como pistas (sofá, nevera, árbol, etc.).","Escribe en cada tarjeta una pista que lleve al siguiente lugar.","Esconde las pistas en orden y el tesoro al final.","Entrega la primera pista al niño y deja que resuelva el resto.","¡Celebra con el tesoro y repite con nuevas pistas!"],"benefits":["Lectura comprensiva","Resolución de problemas","Emoción y motivación"],"tip":"Adapta las pistas al nivel lector del niño: dibujos para los más pequeños, acertijos para los mayores."},"en":{"title":"Treasure Hunt","cat":"🎮 Games","materials":["This printed sheet (clues and map)","Scissors to cut the clue cards","Prize or \"treasure\" to hide","Pen to personalize the clues","Tape to stick clues in locations"],"steps":["Choose 6 locations around the house or yard as clue spots (sofa, fridge, tree, etc.).","Write a clue on each card that leads to the next location.","Hide the clues in order and the treasure at the end.","Give the child the first clue and let them solve the rest.","Celebrate with the treasure and repeat with new clues!"],"benefits":["Reading comprehension","Problem solving","Excitement and motivation"],"tip":"Adapt clues to the child's reading level: drawings for younger kids, riddles for older ones."}},{"id":"mimica","cat":"other","minAge":4,"maxAge":12,"emoji":"🎭","time":"20 min","es":{"title":"Mímica y Charadas","cat":"🎮 Juegos","materials":["Esta ficha impresa","Tijeras para recortar las tarjetas","Bolsa o caja para mezclar las tarjetas","Temporizador (reloj o teléfono)"],"steps":["Recorta las 40 tarjetas con animales, acciones y palabras.","Divide al grupo en 2 equipos.","Un jugador saca una tarjeta y la actúa sin hablar en 60 segundos.","Su equipo adivina. Si aciertan suman 1 punto.","Gana el equipo con más puntos al terminar las tarjetas."],"benefits":["Comunicación no verbal","Trabajo en equipo","Vocabulario y expresión"],"tip":"Para los más pequeños, permite que susurren una sola pista al equipo durante su turno."},"en":{"title":"Charades & Mime","cat":"🎮 Games","materials":["This printed sheet","Scissors to cut the cards","Bag or box to mix the cards","Timer (watch or phone)"],"steps":["Cut out the 40 cards with animals, actions and words.","Divide the group into 2 teams.","A player draws a card and acts it out silently in 60 seconds.","Their team guesses. If correct, they score 1 point.","The team with the most points when cards run out wins."],"benefits":["Non-verbal communication","Teamwork","Vocabulary and expression"],"tip":"For younger children, allow them to whisper one single clue to their team during their turn."}},{"id":"obstaculos","cat":"other","minAge":3,"maxAge":10,"emoji":"🏃","time":"20 min","es":{"title":"Circuito de Obstáculos","cat":"🎮 Juegos","materials":["Cojines, sillas y mantas de casa","Cinta adhesiva para marcar el suelo","Globos (opcional)","Cronómetro","Esta ficha con los 15 retos"],"steps":["MONTA EL CIRCUITO: usa los muebles y objetos de casa para crear estaciones.","Ej: TÚNEL (pasa por debajo de la silla), SALTO (salta los cojines), EQUILIBRIO (camina sobre una línea de cinta).","Añade GIRO (da 3 vueltas y luego camina recto), RASTREO (gatea 3 metros) y LANZAMIENTO (mete una pelota en un cesto).","Cada niño recorre el circuito mientras se le toma el tiempo.","¡Repite y trata de batir tu propio récord!"],"benefits":["Coordinación motriz gruesa","Autocompetencia y superación","Energía física saludable"],"tip":"Toma el tiempo de cada intento — ver cómo mejoran los propios récords motiva muchísimo."},"en":{"title":"Obstacle Course","cat":"🎮 Games","materials":["Home cushions, chairs and blankets","Tape to mark the floor","Balloons (optional)","Stopwatch","This sheet with 15 challenges"],"steps":["SET UP THE COURSE: use furniture and home objects to create stations.","E.g.: TUNNEL (crawl under the chair), JUMP (jump over cushions), BALANCE (walk along a tape line).","Add SPIN (turn 3 times then walk straight), CRAWL (crawl 3 meters) and TOSS (get a ball in a basket).","Each child runs the course while you time them.","Repeat and try to beat your own record!"],"benefits":["Gross motor coordination","Self-competition and improvement","Healthy physical energy"],"tip":"Time every attempt — watching personal records improve is extremely motivating."}},{"id":"bingo","cat":"other","minAge":4,"maxAge":10,"emoji":"🎯","time":"25 min","es":{"title":"Bingo de Animales","cat":"🎮 Juegos","materials":["Esta ficha impresa (4 cartones + lista de animales)","Tijeras","Fichas, botones o semillas para marcar los cuadros","Una bolsa para los cantos"],"steps":["Recorta los 4 cartones de bingo — uno para cada jugador.","Recorta también los nombres de animales y mézclalos en la bolsa.","El animador saca un nombre de la bolsa y lo dice en voz alta.","Quien tenga ese animal en su cartón lo cubre con una ficha.","¡El primero en completar una fila horizontal, vertical o diagonal grita BINGO y gana!"],"benefits":["Atención y concentración","Reconocimiento de palabras","Diversión en grupo"],"tip":"Juega varias rondas cambiando la regla: línea, L, cruz o cartón completo."},"en":{"title":"Animal Bingo","cat":"🎮 Games","materials":["This printed sheet (4 cards + animal list)","Scissors","Chips, buttons or seeds to mark squares","A bag for the call pieces"],"steps":["Cut out the 4 bingo cards — one per player.","Also cut out the animal names and mix them in the bag.","The caller draws a name from the bag and reads it aloud.","Players who have that animal cover it with a chip.","The first to complete a row horizontally, vertically or diagonally shouts BINGO and wins!"],"benefits":["Attention and concentration","Word recognition","Group fun"],"tip":"Play multiple rounds with different rules: line, L-shape, cross or full card."}},{"id":"dados","cat":"other","minAge":5,"maxAge":12,"emoji":"🎲","time":"20 min","es":{"title":"Dados de Cuentos","cat":"🎮 Juegos","materials":["Esta ficha impresa (3 plantillas de dado)","Tijeras","Pegamento o cinta adhesiva","Bolígrafo para personalizar"],"steps":["Recorta las 3 plantillas de dado (personaje, lugar y objeto).","Dobla por las líneas punteadas y pega las pestañas para armar cada dado.","DADO 1 — PERSONAJE: princesa, robot, detective, dragón, niño, mago.","DADO 2 — LUGAR: bosque, ciudad, espacio, submarino, desierto, castillo.","DADO 3 — OBJETO: espejo mágico, mochila voladora, llave dorada, mapa, bote, lámpara.","Tira los 3 dados y crea un cuento con lo que salga — ¡cada lanzamiento da una historia nueva!"],"benefits":["Creatividad narrativa","Vocabulario","Imaginación ilimitada"],"tip":"¡Graba los cuentos con el teléfono! Escucharlos después es aún más divertido que inventarlos."},"en":{"title":"Story Dice","cat":"🎮 Games","materials":["This printed sheet (3 dice templates)","Scissors","Glue or tape","Pen to personalize"],"steps":["Cut out the 3 dice templates (character, setting and object).","Fold along the dotted lines and glue the tabs to form each die.","DIE 1 — CHARACTER: princess, robot, detective, dragon, child, wizard.","DIE 2 — SETTING: forest, city, space, submarine, desert, castle.","DIE 3 — OBJECT: magic mirror, flying backpack, golden key, map, boat, lamp.","Roll all 3 dice and create a story from what comes up — every roll gives a brand new tale!"],"benefits":["Narrative creativity","Vocabulary","Unlimited imagination"],"tip":"Record the stories on your phone! Listening back is even more fun than making them up."}},{"id":"ritmo","cat":"other","minAge":4,"maxAge":10,"emoji":"🥁","time":"20 min","es":{"title":"Ritmo con el Cuerpo","cat":"🎵 Música","materials":["Tus manos y pies","Una silla","Música (opcional)"],"steps":["Siéntate con las manos en las rodillas.","Practica este patrón: palma-palma-rodilla-rodilla.","Acelera poco a poco sin perder el ritmo.","Añade los pies: talón-puntera-talón-puntera.","Combina manos y pies y crea tu propio patrón.","¡Pon música y sigue el ritmo de la canción!"],"benefits":["Coordinación motriz","Sentido del ritmo","Concentración"],"tip":"¡Graba un video del patrón más difícil que logres y muéstraselo a la familia!"},"en":{"title":"Body Rhythm","cat":"🎵 Music","materials":["Your hands and feet","A chair","Music (optional)"],"steps":["Sit down with your hands on your knees.","Practice this pattern: clap-clap-knees-knees.","Speed up little by little without losing the beat.","Add your feet: heel-toe-heel-toe.","Combine hands and feet and make your own pattern.","Put on music and follow the song's rhythm!"],"benefits":["Motor coordination","Sense of rhythm","Focus"],"tip":"Record a video of the hardest pattern you can do and show it to your family!"}},{"id":"instrumento","cat":"other","minAge":5,"maxAge":12,"emoji":"🎺","time":"30 min","es":{"title":"Instrumento Casero","cat":"🎵 Música","materials":["Botella de plástico vacía","Arroz o semillas secas","Cinta adhesiva","Palitos de madera o cucharas"],"steps":["Echa arroz o semillas en la botella hasta la mitad.","Cierra bien con la tapa y sella con cinta.","Agita la botella: ¡ya tienes una maraca!","Coge dos palitos y golpea una superficie dura: ¡son tus palillos de batería!","Combina maraca y palillos para tocar un ritmo.","Decora el instrumento con papeles de colores."],"benefits":["Creatividad","Motricidad fina","Expresión musical"],"tip":"Llena varias botellas con diferente cantidad de arroz: ¡cada una suena distinto!"},"en":{"title":"Homemade Instrument","cat":"🎵 Music","materials":["Empty plastic bottle","Rice or dry seeds","Adhesive tape","Wooden sticks or spoons"],"steps":["Pour rice or seeds into the bottle until half-full.","Close tightly with the cap and seal with tape.","Shake the bottle — you've got a maraca!","Take two sticks and tap a hard surface: they're your drumsticks!","Combine maraca and sticks to play a rhythm.","Decorate the instrument with coloured paper."],"benefits":["Creativity","Fine motor skills","Musical expression"],"tip":"Fill several bottles with different amounts of rice — each one sounds different!"}},{"id":"notas","cat":"other","minAge":6,"maxAge":12,"emoji":"🎵","time":"25 min","es":{"title":"Aprende las Notas","cat":"🎵 Música","materials":["Papel","Lápices de colores","Una regla"],"steps":["Dibuja cinco líneas horizontales paralelas (pentagrama).","Escribe DO, RE, MI, FA, SOL, LA, SI en cada posición.","Colorea cada nota de un color diferente.","Canta las notas siguiendo el pentagrama de abajo a arriba.","Inventa una melodía corta usando solo DO-MI-SOL.","Toca la melodía dando palmadas: una palmada por nota."],"benefits":["Lectura musical básica","Memoria auditiva","Creatividad"],"tip":"¡Dibuja las notas en tarjetas y úsalas para componer canciones cambiándolas de orden!"},"en":{"title":"Learn the Notes","cat":"🎵 Music","materials":["Paper","Coloured pencils","A ruler"],"steps":["Draw five parallel horizontal lines (a staff).","Write DO, RE, MI, FA, SOL, LA, SI at each position.","Colour each note a different colour.","Sing the notes following the staff from bottom to top.","Invent a short melody using only DO-MI-SOL.","Play the melody by clapping: one clap per note."],"benefits":["Basic music reading","Auditory memory","Creativity"],"tip":"Draw the notes on cards and use them to compose songs by changing their order!"}},{"id":"cancion","cat":"other","minAge":6,"maxAge":14,"emoji":"🎤","time":"35 min","es":{"title":"Crea tu Canción","cat":"🎵 Música","materials":["Papel y bolígrafo","Tu voz","Un instrumento (opcional)"],"steps":["Elige un tema: tu animal favorito, las vacaciones, tu familia…","Escribe cuatro frases cortas sobre ese tema.","Intenta que las frases 1 y 3 rimen, y las frases 2 y 4 también.","Inventa una melodía simple: tararea algo que te guste.","Canta tus frases con esa melodía.","¡Ensaya y actúa para alguien de casa!"],"benefits":["Expresión creativa","Lenguaje y rima","Confianza"],"tip":"No importa si la melodía es sencilla — lo más importante es que sea tuya."},"en":{"title":"Create Your Song","cat":"🎵 Music","materials":["Paper and pen","Your voice","An instrument (optional)"],"steps":["Choose a theme: your favourite animal, holidays, your family…","Write four short phrases about that theme.","Try to make phrases 1 & 3 rhyme, and phrases 2 & 4 rhyme.","Invent a simple melody: hum something you like.","Sing your phrases with that melody.","Rehearse and perform it for someone at home!"],"benefits":["Creative expression","Language and rhyme","Confidence"],"tip":"It doesn't matter if the melody is simple — the most important thing is that it's yours."}},{"id":"baile","cat":"other","minAge":4,"maxAge":12,"emoji":"💃","time":"30 min","es":{"title":"Mi Coreografía","cat":"🎵 Música","materials":["Una canción que te guste","Espacio para moverte"],"steps":["Pon tu canción favorita y escúchala entera una vez.","Inventa un movimiento para el estribillo (la parte que se repite).","Añade dos movimientos para el resto de la canción.","Combina todos los movimientos y ensaya 3 veces.","Ponle un nombre a tu coreografía.","¡Actúa delante de tu familia o graba un video!"],"benefits":["Expresión corporal","Memoria secuencial","Autoestima"],"tip":"Empieza con movimientos simples: saltos, giros, aplausos — ¡funcionan genial!"},"en":{"title":"My Choreography","cat":"🎵 Music","materials":["A song you like","Space to move"],"steps":["Put on your favourite song and listen to it all the way through once.","Invent a move for the chorus (the part that repeats).","Add two moves for the rest of the song.","Combine all the moves and rehearse 3 times.","Give your choreography a name.","Perform it for your family or record a video!"],"benefits":["Body expression","Sequential memory","Self-esteem"],"tip":"Start with simple moves: jumps, spins, claps — they work great!"}},{"id":"hojas","cat":"science","minAge":4,"maxAge":10,"emoji":"🍃","time":"30 min","es":{"title":"Arte con Hojas","cat":"🌿 Naturaleza","materials":["Hojas de distintos árboles","Papel blanco","Crayones o lápices de colores"],"steps":["Recoge 5-8 hojas de diferentes formas y tamaños.","Coloca una hoja debajo del papel blanco.","Frota suavemente con el crayón sobre el papel: ¡aparece la hoja!","Repite con todas las hojas usando colores diferentes.","Recorta algunas y pégalas en un cartón para hacer un collage.","Escribe el nombre del árbol al lado de cada hoja si lo sabes."],"benefits":["Observación de la naturaleza","Motricidad fina","Creatividad"],"tip":"Las hojas con nervios muy marcados dan los mejores resultados al frotar."},"en":{"title":"Leaf Art","cat":"🌿 Nature","materials":["Leaves from different trees","White paper","Crayons or coloured pencils"],"steps":["Collect 5-8 leaves of different shapes and sizes.","Place a leaf under the white paper.","Gently rub a crayon over the paper — the leaf appears!","Repeat with all the leaves using different colours.","Cut some out and glue them on card to make a collage.","Write the tree's name next to each leaf if you know it."],"benefits":["Nature observation","Fine motor skills","Creativity"],"tip":"Leaves with very prominent veins give the best results when rubbing."}},{"id":"aves","cat":"science","minAge":5,"maxAge":12,"emoji":"🐦","time":"40 min","es":{"title":"Observa los Pájaros","cat":"🌿 Naturaleza","materials":["Cuaderno o papel","Lápices de colores","Prismáticos (opcional)"],"steps":["Siéntate cerca de una ventana o sal al jardín/parque.","Espera en silencio 5 minutos observando.","Cuando veas un pájaro, dibuja su silueta rápidamente.","Anota: ¿de qué color es? ¿Qué tamaño tiene? ¿Qué hace?","Intenta identificarlo con un libro o una app de aves.","Lleva un registro de todos los pájaros que encuentres."],"benefits":["Paciencia y observación","Conexión con la naturaleza","Ciencias naturales"],"tip":"El amanecer y el atardecer son los mejores momentos para ver más pájaros."},"en":{"title":"Birdwatching","cat":"🌿 Nature","materials":["Notebook or paper","Coloured pencils","Binoculars (optional)"],"steps":["Sit near a window or go to the garden/park.","Wait quietly for 5 minutes and observe.","When you spot a bird, quickly sketch its silhouette.","Note: what colour is it? How big? What is it doing?","Try to identify it with a book or a bird app.","Keep a log of all the birds you find."],"benefits":["Patience and observation","Connection with nature","Natural sciences"],"tip":"Dawn and dusk are the best times to spot more birds."}},{"id":"tiempo","cat":"science","minAge":5,"maxAge":12,"emoji":"☁️","time":"10 min/día","es":{"title":"Diario del Tiempo","cat":"🌿 Naturaleza","materials":["Cuaderno","Lápices de colores","Termómetro (opcional)"],"steps":["Crea una tabla con 7 columnas (una por día de la semana).","Cada mañana observa el cielo y dibuja el tiempo: sol, nubes, lluvia, viento.","Escribe la temperatura si tienes termómetro.","Describe con una palabra cómo se siente el aire: frío, cálido, húmedo…","Al final de la semana, analiza: ¿qué día fue más soleado? ¿llovió mucho?","¡Compara tu diario con el parte meteorológico de la tele!"],"benefits":["Ciencias atmosféricas","Hábito de observación","Análisis de datos"],"tip":"Lleva el diario durante un mes entero para ver los cambios de temporada."},"en":{"title":"Weather Journal","cat":"🌿 Nature","materials":["Notebook","Coloured pencils","Thermometer (optional)"],"steps":["Create a table with 7 columns (one for each day of the week).","Each morning, observe the sky and draw the weather: sun, clouds, rain, wind.","Write the temperature if you have a thermometer.","Describe the air in one word: cold, warm, humid…","At the end of the week, analyse: which day was sunniest? Did it rain much?","Compare your journal with the TV weather forecast!"],"benefits":["Atmospheric science","Observation habit","Data analysis"],"tip":"Keep the journal for a whole month to see seasonal changes."}},{"id":"luna_fases","cat":"science","minAge":6,"maxAge":12,"emoji":"🌙","time":"28 días","es":{"title":"Fases de la Luna","cat":"🌿 Naturaleza","materials":["Papel","Lápiz negro","Linterna (opcional)"],"steps":["Dibuja 8 círculos en una hoja y etiquétalos: Luna nueva, Creciente, Cuarto creciente, Gibosa creciente, Llena, Gibosa menguante, Cuarto menguante, Menguante.","Cada noche (si está despejado) mira la luna y colorea el círculo correspondiente.","Comprueba si tu observación coincide con las fases oficiales.","Anota cuántos días tarda en pasar de luna nueva a luna llena.","Investiga: ¿por qué cambia la forma de la luna?","¡Dibuja el ciclo completo en un círculo grande como un reloj!"],"benefits":["Astronomía básica","Observación sistemática","Paciencia"],"tip":"Usa una app de astronomía para ver el nombre oficial de la fase de cada noche."},"en":{"title":"Moon Phases","cat":"🌿 Nature","materials":["Paper","Black pencil","Torch (optional)"],"steps":["Draw 8 circles on a sheet and label them: New Moon, Waxing Crescent, First Quarter, Waxing Gibbous, Full Moon, Waning Gibbous, Last Quarter, Waning Crescent.","Each night (if clear) look at the moon and colour the matching circle.","Check if your observation matches the official phases.","Note how many days it takes to go from new moon to full moon.","Research: why does the shape of the moon change?","Draw the complete cycle in a large circle like a clock!"],"benefits":["Basic astronomy","Systematic observation","Patience"],"tip":"Use an astronomy app to see the official name of each night's phase."}},{"id":"bichos","cat":"science","minAge":4,"maxAge":10,"emoji":"🐛","time":"45 min","es":{"title":"Explorador de Bichos","cat":"🌿 Naturaleza","materials":["Lupa","Cuaderno","Lápices","Tarro de cristal (opcional)"],"steps":["Busca un jardín, parque o maceta grande.","Con la lupa, examina la tierra, las hojas y las piedras.","Cuando encuentres un bicho, dibújalo y anota: ¿cuántas patas tiene? ¿tiene alas?","Si tienes tarro, mételo con cuidado, obsérvalo 10 minutos y suéltalo.","Intenta identificar qué bicho es con un libro o internet.","Crea una \"ficha de explorador\" para cada bicho que encuentres."],"benefits":["Biología","Curiosidad científica","Respeto por la naturaleza"],"tip":"Los mejores sitios para encontrar bichos son debajo de las piedras y en la corteza de los árboles."},"en":{"title":"Bug Explorer","cat":"🌿 Nature","materials":["Magnifying glass","Notebook","Pencils","Glass jar (optional)"],"steps":["Find a garden, park or large plant pot.","Use the magnifying glass to examine soil, leaves and stones.","When you find a bug, draw it and note: how many legs? Does it have wings?","If you have a jar, gently put it inside, observe for 10 minutes and release it.","Try to identify the bug using a book or the internet.","Create an \"explorer card\" for each bug you find."],"benefits":["Biology","Scientific curiosity","Respect for nature"],"tip":"The best places to find bugs are under stones and in tree bark."}},{"id":"olimpiadas","cat":"other","minAge":5,"maxAge":12,"emoji":"🏅","time":"45 min","es":{"title":"Mini Olimpiadas en Casa","cat":"🏃 Deportes","materials":["Cinta adhesiva para marcar","Calcetines o globos","Cucharas","Cronómetro"],"steps":["Diseña 5 pruebas: salto de longitud, carrera, equilibrio, lanzamiento y relevos.","Marca las líneas de salida y meta con cinta.","Para salto: mide la distancia con una regla y anota el récord.","Para lanzamiento: intenta meter calcetines en un cubo.","Para equilibrio: camina con un globo entre las rodillas.","¡Entrega medallas de papel al ganador de cada prueba!"],"benefits":["Actividad física","Espíritu deportivo","Organización"],"tip":"Crea una tabla de puntuación y repite las olimpiadas cada mes para batir récords."},"en":{"title":"Mini Home Olympics","cat":"🏃 Sports","materials":["Adhesive tape for marking","Socks or balloons","Spoons","Stopwatch"],"steps":["Design 5 events: long jump, race, balance, throwing and relay.","Mark start and finish lines with tape.","For jump: measure the distance with a ruler and record the best.","For throwing: try to get socks into a bucket.","For balance: walk with a balloon between your knees.","Give paper medals to the winner of each event!"],"benefits":["Physical activity","Sportsmanship","Organisation"],"tip":"Create a scoreboard and repeat the Olympics each month to break records."}},{"id":"futbol","cat":"other","minAge":5,"maxAge":14,"emoji":"⚽","time":"30 min","es":{"title":"Trucos de Fútbol","cat":"🏃 Deportes","materials":["Un balón de fútbol (o de goma)","Espacio abierto"],"steps":["Empieza con el control básico: da 10 toques con el pie derecho sin que caiga.","Repite con el pie izquierdo: intenta llegar a 5 toques.","Practica el pase: chuta contra una pared y controla el rebote.","Intenta el caño: pasa la pelota entre dos conos o botellas.","Aprende el regate: mueve la pelota en zigzag entre conos.","¡Crea tu propio truco y ponle un nombre!"],"benefits":["Coordinación","Perseverancia","Habilidad técnica"],"tip":"Grábate en video para ver tus errores y mejorar más rápido."},"en":{"title":"Football Tricks","cat":"🏃 Sports","materials":["A football (or rubber ball)","Open space"],"steps":["Start with basic control: do 10 touches with your right foot without dropping.","Repeat with the left foot: try to reach 5 touches.","Practise passing: kick against a wall and control the rebound.","Try the nutmeg: pass the ball between two cones or bottles.","Learn the dribble: move the ball in a zigzag between cones.","Create your own trick and give it a name!"],"benefits":["Coordination","Perseverance","Technical skill"],"tip":"Film yourself to see your mistakes and improve faster."}},{"id":"atletismo","cat":"other","minAge":6,"maxAge":14,"emoji":"🏆","time":"40 min","es":{"title":"Atletismo Casero","cat":"🏃 Deportes","materials":["Cinta métrica","Cinta adhesiva","Cronómetro","Tiza (si hay acera)"],"steps":["Elige tres pruebas: velocidad (20 m lisos), salto de longitud y lanzamiento de globo de agua.","Marca la pista con cinta o tiza.","Calienta 5 minutos: trote suave y estiramientos.","Realiza cada prueba dos veces y quédate con el mejor intento.","Mide y anota los resultados en una tabla personal.","Repite en 2 semanas: ¿superaste tu marca?"],"benefits":["Condición física","Mentalidad de mejora continua","Disciplina"],"tip":"Establece una \"marca personal\" y celebra cada vez que la superes."},"en":{"title":"Home Athletics","cat":"🏃 Sports","materials":["Tape measure","Adhesive tape","Stopwatch","Chalk (if pavement)"],"steps":["Choose three events: speed (20 m sprint), long jump and water-balloon throw.","Mark the track with tape or chalk.","Warm up for 5 minutes: gentle jog and stretches.","Perform each event twice and keep the best attempt.","Measure and record the results in a personal table.","Repeat in 2 weeks: did you beat your mark?"],"benefits":["Physical fitness","Continuous improvement mindset","Discipline"],"tip":"Set a \"personal best\" and celebrate every time you beat it."}},{"id":"balon","cat":"other","minAge":5,"maxAge":12,"emoji":"🏀","time":"25 min","es":{"title":"Retos con Balón","cat":"🏃 Deportes","materials":["Un balón de baloncesto o de goma","Una papelera o cubo"],"steps":["Reto 1: bota el balón 20 veces seguidas sin que se escape.","Reto 2: bótalo alternando mano derecha e izquierda.","Reto 3: lanza al cubo desde 1 m — ¿metes 5 de 10?","Reto 4: retrocede 50 cm cada vez que metas dos seguidas.","Reto 5: cronometra cuánto tardas en hacer 50 botes.","¡Intenta mejorar tu tiempo cada día!"],"benefits":["Coordinación mano-ojo","Concentración","Perseverancia"],"tip":"Practica con la mano no dominante — en unas semanas notarás una gran mejoría."},"en":{"title":"Ball Challenges","cat":"🏃 Sports","materials":["A basketball or rubber ball","A wastepaper basket or bucket"],"steps":["Challenge 1: dribble the ball 20 times in a row without losing it.","Challenge 2: dribble alternating right and left hand.","Challenge 3: shoot into the bucket from 1 m — can you score 5 out of 10?","Challenge 4: move back 50 cm each time you score two in a row.","Challenge 5: time how long it takes you to do 50 dribbles.","Try to beat your time every day!"],"benefits":["Hand-eye coordination","Focus","Perseverance"],"tip":"Practise with your non-dominant hand — in a few weeks you'll notice a huge improvement."}},{"id":"natacion","cat":"other","minAge":5,"maxAge":12,"emoji":"🏊","time":"20 min","es":{"title":"Preparación para Nadar","cat":"🏃 Deportes","materials":["Espacio en el suelo","Esterilla (opcional)","Botella de agua"],"steps":["Aprende la posición horizontal: échate boca abajo y estira los brazos al frente.","Practica el movimiento de brazos de crol: alternando derecha e izquierda.","Añade el pateo de piernas: piernas rectas, movimiento desde la cadera.","Combina brazos y piernas durante 30 segundos.","Practica la respiración: gira la cabeza a un lado al mover el brazo.","Repite la secuencia 3 veces y descansa bebiendo agua."],"benefits":["Coordinación corporal","Preparación física","Seguridad acuática"],"tip":"Este ejercicio seco en casa te ayuda a aprender los movimientos antes de entrar al agua."},"en":{"title":"Swimming Prep","cat":"🏃 Sports","materials":["Floor space","Mat (optional)","Water bottle"],"steps":["Learn the horizontal position: lie face down and stretch your arms forward.","Practise the freestyle arm stroke: alternating right and left.","Add the leg kick: straight legs, movement from the hip.","Combine arms and legs for 30 seconds.","Practise breathing: turn your head to one side as you move your arm.","Repeat the sequence 3 times and rest by drinking water."],"benefits":["Body coordination","Physical preparation","Water safety"],"tip":"This dry-land exercise at home helps you learn the movements before getting in the water."}}];
